// Synthetic PIV: particle images rendered from a known flow, and a standard cross-correlation evaluation.
// Theoretical exercise only: the images are generated by this program, no recorded images are used.
// Pure functions, no DOM.

'use strict';

// ---------- random numbers (seeded, so every run gives the same images) ----------
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function gaussian(rand) {
  let u = 0;
  while (u === 0) u = rand();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * rand());
}

// Error function, Abramowitz and Stegun 7.1.26 (absolute error below 1.5e-7).
function erf(x) {
  const s = x < 0 ? -1 : 1;
  x = Math.abs(x);
  const t = 1 / (1 + 0.3275911 * x);
  const y = 1 - ((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-x * x);
  return s * y;
}

// ---------- image rendering ----------
// Particle image: Gaussian spot I0 exp(-8 r^2 / d^2) (d = e^-2 diameter in pixels), integrated over each pixel.
// parts: array of [x, y, I0] in pixels (pixel centres at integer coordinates).
function renderImage(w, h, parts, d, opts) {
  opts = opts || {};
  const img = new Float32Array(w * h);
  const sig = d / 4;
  const k = 1 / (Math.SQRT2 * sig);
  const norm = erf(0.5 * k);                 // pixel fraction of a centred particle, so its peak pixel is I0
  const R = Math.ceil(2.5 * sig + 1);
  for (const [px, py, I0] of parts) {
    const x0 = Math.round(px), y0 = Math.round(py);
    if (x0 < -R || y0 < -R || x0 >= w + R || y0 >= h + R) continue;
    const ex = [], ey = [];
    for (let q = -R; q <= R; q++) {
      ex.push(0.5 * (erf((x0 + q + 0.5 - px) * k) - erf((x0 + q - 0.5 - px) * k)) / norm);
      ey.push(0.5 * (erf((y0 + q + 0.5 - py) * k) - erf((y0 + q - 0.5 - py) * k)) / norm);
    }
    for (let b = -R; b <= R; b++) {
      const y = y0 + b;
      if (y < 0 || y >= h) continue;
      for (let a = -R; a <= R; a++) {
        const x = x0 + a;
        if (x < 0 || x >= w) continue;
        img[y * w + x] += I0 * ex[a + R] * ey[b + R];
      }
    }
  }
  return img;
}

// Background, camera noise and 8-bit quantisation, plus an optional mask (pixels with mask = 1 are set to the
// background only: used for the bubble, which shows no particles).
function finishImage(img, w, h, rand, opts) {
  opts = opts || {};
  const bg = opts.background === undefined ? 6 : opts.background;
  const noise = opts.noise === undefined ? 2 : opts.noise;
  const out = new Uint8Array(w * h);
  for (let i = 0; i < w * h; i++) {
    let v = (opts.mask && opts.mask[i]) ? bg * 0.4 : img[i] + bg;
    v += noise * gaussian(rand);
    out[i] = Math.max(0, Math.min(255, Math.round(v)));
  }
  return out;
}

// ---------- FFT (radix 2, in place) ----------
function fft1(re, im, inv) {
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) { let t = re[i]; re[i] = re[j]; re[j] = t; t = im[i]; im[i] = im[j]; im[j] = t; }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (inv ? 2 : -2) * Math.PI / len;
    const wr = Math.cos(ang), wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1, ci = 0;
      for (let j = 0; j < len / 2; j++) {
        const a = i + j, b = a + len / 2;
        const xr = re[b] * cr - im[b] * ci, xi = re[b] * ci + im[b] * cr;
        re[b] = re[a] - xr; im[b] = im[a] - xi;
        re[a] += xr; im[a] += xi;
        const t = cr * wr - ci * wi; ci = cr * wi + ci * wr; cr = t;
      }
    }
  }
  if (inv) for (let i = 0; i < n; i++) { re[i] /= n; im[i] /= n; }
}
function fft2(re, im, n, inv) {
  const rr = new Float64Array(n), ri = new Float64Array(n);
  for (let y = 0; y < n; y++) {
    for (let x = 0; x < n; x++) { rr[x] = re[y * n + x]; ri[x] = im[y * n + x]; }
    fft1(rr, ri, inv);
    for (let x = 0; x < n; x++) { re[y * n + x] = rr[x]; im[y * n + x] = ri[x]; }
  }
  for (let x = 0; x < n; x++) {
    for (let y = 0; y < n; y++) { rr[y] = re[y * n + x]; ri[y] = im[y * n + x]; }
    fft1(rr, ri, inv);
    for (let y = 0; y < n; y++) { re[y * n + x] = rr[y]; im[y * n + x] = ri[y]; }
  }
}

// ---------- cross-correlation of one window pair ----------
// A window of size n at top-left (ax, ay) in image A, the same size at (bx, by) in image B.
// Returns the displacement of the correlation peak [dx, dy] (B relative to A) with a three-point Gaussian
// sub-pixel fit, and the ratio of the highest to the second-highest peak.
function correlate(A, B, w, h, ax, ay, bx, by, n) {
  const ar = new Float64Array(n * n), ai = new Float64Array(n * n);
  const br = new Float64Array(n * n), bi = new Float64Array(n * n);
  let ma = 0, mb = 0;
  for (let y = 0; y < n; y++) {
    for (let x = 0; x < n; x++) {
      const xa = ax + x, ya = ay + y, xb = bx + x, yb = by + y;
      const va = xa >= 0 && ya >= 0 && xa < w && ya < h ? A[ya * w + xa] : 0;
      const vb = xb >= 0 && yb >= 0 && xb < w && yb < h ? B[yb * w + xb] : 0;
      ar[y * n + x] = va; br[y * n + x] = vb; ma += va; mb += vb;
    }
  }
  ma /= n * n; mb /= n * n;
  let ea = 0, eb = 0;
  for (let i = 0; i < n * n; i++) { ar[i] -= ma; br[i] -= mb; ea += ar[i] * ar[i]; eb += br[i] * br[i]; }
  if (ea === 0 || eb === 0) return null;
  fft2(ar, ai, n, false);
  fft2(br, bi, n, false);
  // R = IFFT(conj(FA) FB): peak at the displacement of B relative to A
  for (let i = 0; i < n * n; i++) {
    const r = ar[i] * br[i] + ai[i] * bi[i];
    const im = ar[i] * bi[i] - ai[i] * br[i];
    ar[i] = r; ai[i] = im;
  }
  fft2(ar, ai, n, true);
  const norm = 1 / Math.sqrt(ea * eb);
  const R = (dx, dy) => ar[(((dy % n) + n) % n) * n + (((dx % n) + n) % n)] * norm;
  // peak search within +-n/2
  let best = -Infinity, px = 0, py = 0;
  for (let dy = -n / 2 + 1; dy < n / 2; dy++) {
    for (let dx = -n / 2 + 1; dx < n / 2; dx++) {
      const v = R(dx, dy);
      if (v > best) { best = v; px = dx; py = dy; }
    }
  }
  // second peak, outside a 3x3 neighbourhood of the first
  let second = 0;
  for (let dy = -n / 2 + 1; dy < n / 2; dy++) {
    for (let dx = -n / 2 + 1; dx < n / 2; dx++) {
      if (Math.abs(dx - px) <= 1 && Math.abs(dy - py) <= 1) continue;
      const v = R(dx, dy);
      if (v > second) second = v;
    }
  }
  const sub = (m, c, p) => {
    if (m > 0 && c > 0 && p > 0) {
      const lm = Math.log(m), lc = Math.log(c), lp = Math.log(p);
      const den = 2 * (lm - 2 * lc + lp);
      return den !== 0 ? (lm - lp) / den : 0;
    }
    const den = 2 * (m - 2 * c + p);
    return den !== 0 ? (m - p) / den : 0;
  };
  const c0 = R(px, py);
  const sx = sub(R(px - 1, py), c0, R(px + 1, py));
  const sy = sub(R(px, py - 1), c0, R(px, py + 1));
  return { dx: px + sx, dy: py + sy, peak: best, ratio: second > 0 ? best / second : Infinity };
}

// ---------- full evaluation ----------
// Two passes: a first pass without window offset, then a second pass with a discrete window offset from the
// validated first-pass field (Westerweel, Dabiri and Gharib 1997). Outliers are found with the normalised
// median test (Westerweel and Scarano 2005) and replaced by the median of their neighbours.
// masked(xc, yc) -> true where no vector should be computed (inside the bubble).
function evaluate(A, B, w, h, opts) {
  opts = opts || {};
  const n = opts.window || 32, step = opts.step || 16;
  const masked = opts.masked || (() => false);
  const nx = Math.floor((w - n) / step) + 1, ny = Math.floor((h - n) / step) + 1;
  const cx = new Float64Array(nx), cy = new Float64Array(ny);
  for (let i = 0; i < nx; i++) cx[i] = i * step + (n - 1) / 2;
  for (let j = 0; j < ny; j++) cy[j] = j * step + (n - 1) / 2;
  const U = new Float64Array(nx * ny), V = new Float64Array(nx * ny);
  const valid = new Uint8Array(nx * ny), outlier = new Uint8Array(nx * ny), mask = new Uint8Array(nx * ny);
  for (let j = 0; j < ny; j++) for (let i = 0; i < nx; i++) mask[j * nx + i] = masked(cx[i], cy[j]) ? 1 : 0;

  const pass = (offU, offV) => {
    for (let j = 0; j < ny; j++) {
      for (let i = 0; i < nx; i++) {
        const k = j * nx + i;
        valid[k] = 0;
        if (mask[k]) continue;
        const ox = offU ? Math.round(offU[k]) : 0, oy = offV ? Math.round(offV[k]) : 0;
        const x0 = i * step, y0 = j * step;
        const ax = x0 - Math.floor(ox / 2), ay = y0 - Math.floor(oy / 2);
        const r = correlate(A, B, w, h, ax, ay, ax + ox, ay + oy, n);
        if (!r) continue;
        U[k] = ox + r.dx; V[k] = oy + r.dy; valid[k] = 1;
      }
    }
  };
  const validate = () => {
    const eps = 0.1, thr = 2;
    outlier.fill(0);
    const med = (a) => { a.sort((p, q) => p - q); const m = a.length >> 1; return a.length % 2 ? a[m] : 0.5 * (a[m - 1] + a[m]); };
    for (let j = 0; j < ny; j++) {
      for (let i = 0; i < nx; i++) {
        const k = j * nx + i;
        if (!valid[k]) continue;
        for (const comp of [U, V]) {
          const nb = [];
          for (let b = -1; b <= 1; b++) for (let a = -1; a <= 1; a++) {
            if (!a && !b) continue;
            const ii = i + a, jj = j + b;
            if (ii < 0 || jj < 0 || ii >= nx || jj >= ny) continue;
            const kk = jj * nx + ii;
            if (valid[kk]) nb.push(comp[kk]);
          }
          if (nb.length < 3) continue;
          const m = med(nb.slice());
          const rm = med(nb.map((v) => Math.abs(v - m)));
          if (Math.abs(comp[k] - m) / (rm + eps) > thr) outlier[k] = 1;
        }
      }
    }
    // replace outliers by the median of valid, non-outlier neighbours
    const Ur = U.slice(), Vr = V.slice();
    for (let j = 0; j < ny; j++) for (let i = 0; i < nx; i++) {
      const k = j * nx + i;
      if (!outlier[k]) continue;
      const nu = [], nv = [];
      for (let b = -1; b <= 1; b++) for (let a = -1; a <= 1; a++) {
        const ii = i + a, jj = j + b;
        if ((!a && !b) || ii < 0 || jj < 0 || ii >= nx || jj >= ny) continue;
        const kk = jj * nx + ii;
        if (valid[kk] && !outlier[kk]) { nu.push(U[kk]); nv.push(V[kk]); }
      }
      if (nu.length) { Ur[k] = med(nu); Vr[k] = med(nv); }
    }
    return [Ur, Vr];
  };

  pass(null, null);
  let [Up, Vp] = validate();
  const firstOutliers = outlier.reduce((a, b) => a + b, 0);
  if (opts.passes !== 1) {
    pass(Up, Vp);
    [Up, Vp] = validate();
  }
  let nValid = 0, nOut = 0;
  for (let k = 0; k < nx * ny; k++) { if (valid[k]) nValid++; if (outlier[k]) nOut++; }
  return { nx, ny, cx, cy, U: Up, V: Vp, raw: { U, V }, valid, outlier, mask, nValid, nOut, firstOutliers, window: n, step };
}

// ---------- synthetic recording of the flow around the bubble ----------
// sample(x, z) -> [u_x, u_z, ...] in bubble radii and rise speeds, bubble centre at the origin, z along the flow.
// The camera looks at the plane through the bubble axis; S pixels per bubble radius. Tracers follow the liquid
// exactly. Frame A shows each tracer half a time step before, frame B half a time step after its mid position.
function bubbleRecording(sample, opts) {
  opts = opts || {};
  const S = opts.S || 100, w = opts.w || 500, h = opts.h || 600;
  const xMin = opts.xMin === undefined ? -2.5 : opts.xMin, zMin = opts.zMin === undefined ? -1.8 : opts.zMin;
  const d0 = opts.d0 || 6, ppp = opts.ppp || 0.025, dPart = opts.dPart || 3;
  const noise = opts.noise === undefined ? 2 : opts.noise;
  const dt = d0 / S;                                   // time between frames in units of a / U
  const rand = mulberry32(opts.seed || 2026);
  const toPhys = (px, py) => [xMin + px / S, zMin + py / S];
  const move = (x, z, T) => {                          // RK4 along the liquid velocity, 4 substeps
    const n = 4, hh = T / n;
    for (let k = 0; k < n; k++) {
      const k1 = sample(x, z), k2 = sample(x + 0.5 * hh * k1[0], z + 0.5 * hh * k1[1]);
      const k3 = sample(x + 0.5 * hh * k2[0], z + 0.5 * hh * k2[1]), k4 = sample(x + hh * k3[0], z + hh * k3[1]);
      x += hh / 6 * (k1[0] + 2 * k2[0] + 2 * k3[0] + k4[0]);
      z += hh / 6 * (k1[1] + 2 * k2[1] + 2 * k3[1] + k4[1]);
    }
    return [x, z];
  };
  const margin = Math.ceil(2 * d0 + 4);
  const nP = Math.round(ppp * (w + 2 * margin) * (h + 2 * margin));
  const PA = [], PB = [];
  for (let k = 0; k < nP; k++) {
    const px = -margin + rand() * (w + 2 * margin), py = -margin + rand() * (h + 2 * margin);
    const I0 = 60 + 140 * rand();
    const [x, z] = toPhys(px, py);
    if (Math.hypot(x, z) < 1.002) continue;
    const a = move(x, z, -dt / 2), b = move(x, z, dt / 2);
    if (Math.hypot(a[0], a[1]) < 1 || Math.hypot(b[0], b[1]) < 1) continue;
    PA.push([(a[0] - xMin) * S, (a[1] - zMin) * S, I0]);
    PB.push([(b[0] - xMin) * S, (b[1] - zMin) * S, I0]);
  }
  const mask = new Uint8Array(w * h);
  for (let py = 0; py < h; py++) for (let px = 0; px < w; px++) { const [x, z] = toPhys(px, py); if (Math.hypot(x, z) < 1) mask[py * w + px] = 1; }
  const A = finishImage(renderImage(w, h, PA, dPart), w, h, rand, { mask, noise });
  const B = finishImage(renderImage(w, h, PB, dPart), w, h, rand, { mask, noise });
  return { w, h, A, B, S, xMin, zMin, d0, dt, toPhys, move, nParticles: PA.length };
}

// Evaluate a recording and compare every vector with the exact displacement at its window centre.
// Vectors whose window centre is closer to the bubble surface than one window width are counted separately.
function evaluateRecording(rec, opts) {
  opts = opts || {};
  const res = evaluate(rec.A, rec.B, rec.w, rec.h, Object.assign({}, opts, {
    masked: (cx, cy) => { const [x, z] = rec.toPhys(cx, cy); return Math.hypot(x, z) < 1; },
  }));
  const nearLimit = res.window / rec.S;                // one window width, in bubble radii
  const err = new Float64Array(res.nx * res.ny).fill(NaN), tu = new Float64Array(res.nx * res.ny), tv = new Float64Array(res.nx * res.ny);
  const near = [], far = [];
  let maxE = 0;
  for (let j = 0; j < res.ny; j++) for (let i = 0; i < res.nx; i++) {
    const k = j * res.nx + i;
    if (!res.valid[k]) continue;
    const [x, z] = rec.toPhys(res.cx[i], res.cy[j]);
    const a = rec.move(x, z, -rec.dt / 2), b = rec.move(x, z, rec.dt / 2);
    tu[k] = (b[0] - a[0]) * rec.S; tv[k] = (b[1] - a[1]) * rec.S;
    const e = Math.hypot(res.U[k] - tu[k], res.V[k] - tv[k]);
    err[k] = e;
    if (e > maxE) maxE = e;
    (Math.hypot(x, z) - 1 < nearLimit ? near : far).push(e);
  }
  const rms = (a) => (a.length ? Math.sqrt(a.reduce((p, q) => p + q * q, 0) / a.length / 2) : NaN);   // per component
  return Object.assign(res, { err, trueU: tu, trueV: tv, rmsNear: rms(near), rmsFar: rms(far), nNear: near.length, nFar: far.length, maxErr: maxE });
}

if (typeof module !== 'undefined') {
  module.exports = { mulberry32, gaussian, erf, renderImage, finishImage, fft1, fft2, correlate, evaluate, bubbleRecording, evaluateRecording };
}
